import java.util.Scanner;

class Factorial {

    int findFactorial(int n) {

        int factorial = 1;

        for (int i = 1; i <= n; i++) {
            factorial = factorial * i;
        }

        return factorial;
    }
}

class FactorialApp {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        int n = scan.nextInt();

        Factorial factorial = new Factorial();

        int result =
                factorial.findFactorial(n);

        System.out.println(result);
    }
}

import java.util.Scanner;

class Calculator {

    void printTable(int n) {

        for (int i = 1; i <= 10; i++) {

            System.out.println(
                n + " x " + i + " = " + (n * i)
            );
        }
    }
}

class Main {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        int n = scan.nextInt();

        Calculator calculator =
                new Calculator();

        calculator.printTable(n);
    }
}

import java.util.Scanner;

class Main {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        int n = scan.nextInt();

        int i = 1;

        while (i <= n) {

            System.out.print((2 * i) + " ");

            i++;
        }
    }
}

import java.util.Scanner;

class Demo {

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        int n = scan.nextInt();

        for (int i = 1; i <= n; i++) {

            if (i % 2 == 0 &&
                i % 4 == 0) {

                System.out.print(i + " ");
            }
        }
    }
}

